_sv(f"insert into public.empresa_contatos (empresa_id,nome,email,recebe_faturas) values ({EP},'Financeiro Epsilon','fin@epsilon.invalid',true)")
FR = _sv(f"insert into public.faturas (empresa_id,competencia,valor_total,vencimento,modelo,situacao) values ({EP},'2026-07-01',800,current_date+10,'contrato','rascunho') returning id")
checar("resumo da emissão: quantas, total e contatos", True, f"select quantidade||'|'||total||'|'||contatos from public.resumo_emissao(array[{FR}]::bigint[])", "authenticated", u["admin"], "1|800.00|1")
checar("cliente não vê o resumo da emissão", False, f"select * from public.resumo_emissao(array[{FR}]::bigint[])", "authenticated", ADP)
FV = _sv(f"insert into public.faturas (empresa_id,competencia,valor_total,vencimento,modelo,situacao) values ({EP},'2026-08-01',1200,current_date-12,'contrato','aberta') returning id")
checar("vencida há 12 dias recebe só o lembrete mais recente (7º dia)", True, f"select string_agg(tipo, ',') from public.lembretes_para_enviar() where fatura_id={FV}", "service_role", None, "d7")
checar("site não lista lembretes", False, "select * from public.lembretes_para_enviar()", "authenticated", u["admin"])
checar("10 dias de atraso: empresa fica inadimplente", True, f"set role service_role; select public.atualizar_inadimplencia(); select situacao||'|'||ativa::text from public.empresas where id={EP}", None, None, "inadimplente|false")
checar("cliente vê que o acesso está bloqueado e o motivo", True, f"select situacao||'|'||bloqueada::text||'|'||(motivo like 'Fatura vencida%')::text from public.acesso_da_empresa({EP})", "authenticated", ADP, "inadimplente|true|true")
checar("bloqueado, o cliente ainda vê a fatura para pagar", True, f"select count(*) from public.faturas where id={FV}", "authenticated", ADP, 1)
checar("empresa e equipe recebem o aviso do bloqueio", True, f"select count(*) from public.avisos where empresa_id={EP} and titulo in ('Acesso bloqueado por fatura vencida','Inadimplente · Epsilon Financeira')", "service_role", None, 2)
checar("site não marca inadimplência", False, "select public.atualizar_inadimplencia()", "authenticated", u["admin"])
checar("Administrativo não reativa inadimplente pela troca de situação", False, f"select public.mudar_situacao_empresa({EP}, 'ativa')", "authenticated", ADM)
checar("nem o Master reativa sem prazo pela troca de situação", False, f"select public.mudar_situacao_empresa({EP}, 'ativa')", "authenticated", u["admin"])
checar("Administrativo não libera inadimplente", False, f"select public.liberar_inadimplente({EP}, 'cliente prometeu pagar', current_date + 5)", "authenticated", ADM)
checar("liberação sem motivo é recusada", False, f"select public.liberar_inadimplente({EP}, '')", "authenticated", u["admin"])
checar("liberação acima de 30 dias é recusada", False, f"select public.liberar_inadimplente({EP}, 'acordo com o financeiro', current_date + 31)", "authenticated", u["admin"])
checar("Master libera com a fatura em aberto (padrão 7 dias)", True, f"select (public.liberar_inadimplente({EP}, 'acordo com o financeiro') = (now() at time zone 'America/Sao_Paulo')::date + 7)::text", "authenticated", u["admin"], "true")
checar("liberada: acesso aberto e o prazo para o cliente", True, f"select bloqueada::text||'|'||(liberada_ate = (now() at time zone 'America/Sao_Paulo')::date + 7)::text from public.acesso_da_empresa({EP})", "authenticated", ADP, "false|true")
checar("até o prazo, a rotina não bloqueia de novo", True, f"set role service_role; select public.atualizar_inadimplencia(); select situacao from public.empresas where id={EP}", None, None, "ativa")
checar("cliente e equipe sabem da liberação", True, f"select count(*) from public.avisos where empresa_id={EP} and (titulo like 'Acesso liberado pela MotorCob%' or titulo like 'Inadimplente liberada%')", "service_role", None, 2)
_sv(f"update public.empresas set liberada_ate = (now() at time zone 'America/Sao_Paulo')::date - 1 where id={EP}")
checar("passou o prazo sem pagar: bloqueia de novo", True, f"set role service_role; select public.atualizar_inadimplencia(); select situacao from public.empresas where id={EP}", None, None, "inadimplente")
checar("pagou: o acesso volta sozinho", True, f"set role service_role; update public.faturas set situacao='paga', paga_em=current_date where id={FV}; select situacao||'|'||ativa::text from public.empresas where id={EP}", None, None, "ativa|true")
checar("pagou tudo: a liberação manual deixa de valer", True, f"select coalesce(liberada_ate::text,'nenhuma') from public.empresas where id={EP}", "service_role", None, "nenhuma")
checar("cliente recebe o aviso de acesso liberado", True, f"select count(*) from public.avisos where empresa_id={EP} and titulo='Acesso liberado'", "service_role", None, 1)
F8 = _sv(f"insert into public.faturas (empresa_id,competencia,valor_total,vencimento,modelo,situacao) values ({EP},'2026-09-01',900,current_date-8,'contrato','aberta') returning id")
checar("7º dia: avisa que o acesso será bloqueado em 3 dias, sem bloquear", True, f"set role service_role; select public.atualizar_inadimplencia(); select (select count(*) from public.avisos where chave='bloqueio_em_3:{F8}')||'|'||situacao from public.empresas where id={EP}", None, None, "1|ativa")
